create table if not exists public.reading_source_items (id uuid primary key default gen_random_uuid(),source_key text not null,provider text not null default 'google-drive',root_external_id text not null,external_id text not null,parent_path text not null default '',path text not null default '',name text not null,item_type text not null,format text not null default '',mime_type text not null default '',size_bytes bigint not null default 0,modified_at timestamptz,checksum text not null default '',franchise text not null default '',collection_name text not null default '',issue_label text not null default '',cover_url text not null default '',cover_source text not null default '',metadata jsonb not null default '{}'::jsonb,scan_generation text not null default '',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_key,external_id));
create index if not exists reading_source_items_source_active on public.reading_source_items(source_key,active,item_type);
create index if not exists reading_source_items_franchise on public.reading_source_items(source_key,franchise,collection_name) where active=true;
alter table public.reading_source_items enable row level security;revoke all on public.reading_source_items from anon,authenticated;grant select,insert,update,delete on public.reading_source_items to service_role;
create table if not exists public.reading_sources(source_key text primary key,provider text not null default 'google-drive',name text not null default 'Biblioteca Google Drive',root_external_id text not null,root_url text not null default '',scan_generation text not null default '',last_scan_at timestamptz,item_count integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.reading_sources enable row level security;revoke all on public.reading_sources from anon,authenticated;grant select,insert,update,delete on public.reading_sources to service_role;
create table if not exists public.reading_source_groups(id uuid primary key default gen_random_uuid(),source_key text not null,franchise text not null,title text not null,cover_url text not null default '',cover_source text not null default '',description text not null default '',metadata jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),unique(source_key,franchise));alter table public.reading_source_groups enable row level security;revoke all on public.reading_source_groups from anon,authenticated;grant select,insert,update,delete on public.reading_source_groups to service_role;